repo.readings.py:
"""Reading records."""


class Reading:
    def __init__(self, sensor, level):
        self.sensor = sensor
        self.level = level

    def __repr__(self):
        return "Reading(%r, %r)" % (self.sensor, self.level)


ROWS = [('south', 17), ('north', 26), ('north', 29), ('west', 40), ('east', 53), ('west', 58), ('north', 18)]


def load_readings():
    """Yield the stored readings one at a time."""
    for sensor, level in ROWS:
        yield Reading(sensor, level)

repo.journal.py:
"""A book of readings with a cached total."""


class ReadingBook:
    def __init__(self):
        self._readings = []
        self._total = None

    def add(self, reading):
        """Add one reading to the book."""
        self._readings.append(reading)

    def total(self):
        """Return the total level of the readings in the book."""
        if self._total is None:
            self._total = sum(x.level for x in self._readings)
        return self._total

    def count(self):
        """Return how many readings the book holds."""
        return len(self._readings)


def describe_reading(reading):
    """Return a one-line description of a reading."""
    return "%s: %s" % (reading.sensor, reading.level)

